"use client";

import { useMailStore } from "@/stores/use-mail-store";
import clsx from "clsx";

function formatTime(date: Date) {
  return new Intl.DateTimeFormat('en-US', { hour: 'numeric', minute: 'numeric' }).format(date);
}

export function ThreadList() {
  const { emails, selectedEmailId, selectEmail, filter } = useMailStore();

  const filteredEmails = emails.filter(email => {
    if (filter === 'inbox') return true; // simplified for mock
    if (filter === 'starred') return email.isStarred;
    return false;
  });

  return (
    <div className="w-[350px] lg:w-[400px] border-r flex flex-col h-screen bg-white dark:bg-zinc-950">
      <div className="h-14 flex items-center px-4 border-b flex-shrink-0 bg-white dark:bg-zinc-950 z-10">
        <h2 className="font-semibold text-sm capitalize">{filter}</h2>
      </div>
      
      <div className="flex-1 overflow-y-auto">
        {filteredEmails.map((email) => {
          const isSelected = email.id === selectedEmailId;
          const isCritical = email.priority?.tier === 'critical';

          return (
            <button
              key={email.id}
              onClick={() => selectEmail(email.id)}
              className={clsx(
                "w-full text-left p-4 border-b transition-colors relative flex flex-col gap-1",
                isSelected 
                  ? "bg-blue-50 dark:bg-blue-900/20 border-l-2 border-l-blue-600" 
                  : "hover:bg-zinc-50 dark:hover:bg-zinc-900/50 border-l-2 border-l-transparent"
              )}
            >
              <div className="flex items-center justify-between">
                <span className={clsx(
                  "font-medium text-sm truncate",
                  !email.isRead ? "text-zinc-900 dark:text-zinc-100" : "text-zinc-600 dark:text-zinc-400"
                )}>
                  {email.from.name || email.from.email}
                </span>
                <span className="text-xs text-zinc-400 whitespace-nowrap ml-2" suppressHydrationWarning>
                  {formatTime(email.receivedAt)}
                </span>
              </div>
              
              <div className="flex items-center gap-2">
                <span className={clsx(
                  "text-sm truncate",
                  !email.isRead ? "text-zinc-900 font-medium dark:text-zinc-100" : "text-zinc-500 dark:text-zinc-400"
                )}>
                  {email.subject}
                </span>
                {isCritical && (
                  <span className="bg-red-100 text-red-600 dark:bg-red-900/30 dark:text-red-400 text-[10px] uppercase font-bold px-1.5 py-0.5 rounded flex-shrink-0">
                    Urgent
                  </span>
                )}
              </div>
              
              <p className="text-xs text-zinc-500 dark:text-zinc-400 line-clamp-2 mt-1">
                {email.snippet}
              </p>
              
              {!email.isRead && (
                <div className="absolute top-4 left-2 w-2 h-2 bg-blue-600 rounded-full" />
              )}
            </button>
          );
        })}
        {filteredEmails.length === 0 && (
          <div className="flex flex-col items-center justify-center h-full text-zinc-500 p-8 text-center">
            <p className="text-sm">Nothing to see here.</p>
            <p className="text-xs mt-1">You're all caught up!</p>
          </div>
        )}
      </div>
    </div>
  );
}
