"use client";

import { useMailStore } from "@/stores/use-mail-store";
import { Sparkles, Reply, Forward, Archive, Trash2, MoreHorizontal } from "lucide-react";
import clsx from "clsx";

function formatFullDate(date: Date) {
  return new Intl.DateTimeFormat('en-US', { 
    weekday: 'short', month: 'short', day: 'numeric', 
    hour: 'numeric', minute: 'numeric' 
  }).format(date);
}

export function EmailDetail() {
  const { emails, selectedEmailId, archiveEmail, deleteEmail } = useMailStore();
  
  const email = emails.find(e => e.id === selectedEmailId);

  if (!email) {
    return (
      <div className="flex-1 flex flex-col items-center justify-center bg-zinc-50/50 dark:bg-zinc-900/20 text-zinc-400">
        <div className="w-16 h-16 mb-4 rounded-2xl bg-zinc-100 dark:bg-zinc-800 flex items-center justify-center">
          <Sparkles className="w-8 h-8 text-zinc-300 dark:text-zinc-600" />
        </div>
        <p>Select a thread to read</p>
      </div>
    );
  }

  return (
    <div className="flex-1 flex flex-col h-screen bg-white dark:bg-zinc-950 overflow-hidden">
      {/* Top Action Bar */}
      <div className="h-14 flex items-center justify-between px-6 border-b flex-shrink-0">
        <div className="flex items-center gap-2">
          <button onClick={() => archiveEmail(email.id)} className="p-2 text-zinc-500 hover:text-zinc-900 hover:bg-zinc-100 dark:hover:bg-zinc-800 rounded-md transition-colors" title="Archive (E)">
            <Archive className="w-4 h-4" />
          </button>
          <button onClick={() => deleteEmail(email.id)} className="p-2 text-zinc-500 hover:text-zinc-900 hover:bg-zinc-100 dark:hover:bg-zinc-800 rounded-md transition-colors" title="Delete (#)">
            <Trash2 className="w-4 h-4" />
          </button>
        </div>
        <div className="flex items-center gap-2">
          <button className="flex items-center gap-2 px-3 py-1.5 text-sm bg-gradient-to-r from-blue-600 to-indigo-600 text-white rounded-md shadow-sm hover:from-blue-700 hover:to-indigo-700 transition-colors">
            <Sparkles className="w-4 h-4" />
            AI Draft Reply
          </button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto">
        <div className="max-w-3xl mx-auto py-8 px-6">
          <h1 className="text-2xl font-semibold mb-8 text-zinc-900 dark:text-zinc-100">
            {email.subject}
          </h1>

          <div className="flex items-start justify-between mb-8">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-full bg-gradient-to-br from-indigo-100 to-blue-100 dark:from-indigo-900/50 dark:to-blue-900/50 flex items-center justify-center text-blue-700 dark:text-blue-300 font-semibold text-lg border border-blue-200/50 dark:border-blue-800/50 shadow-sm">
                {(email.from.name || email.from.email).charAt(0).toUpperCase()}
              </div>
              <div>
                <div className="flex items-center gap-2">
                  <span className="font-semibold text-sm">{email.from.name}</span>
                  <span className="text-xs text-zinc-500">&lt;{email.from.email}&gt;</span>
                </div>
                <div className="text-xs text-zinc-400 mt-0.5">
                  to {email.to.map(t => t.name || t.email).join(', ')}
                </div>
              </div>
            </div>
            <div className="text-xs text-zinc-400 flex items-center gap-4" suppressHydrationWarning>
              {formatFullDate(email.receivedAt)}
              <div className="flex items-center gap-1">
                <button className="p-1.5 hover:bg-zinc-100 dark:hover:bg-zinc-800 rounded text-zinc-400 transition-colors"><Reply className="w-4 h-4" /></button>
                <button className="p-1.5 hover:bg-zinc-100 dark:hover:bg-zinc-800 rounded text-zinc-400 transition-colors"><MoreHorizontal className="w-4 h-4" /></button>
              </div>
            </div>
          </div>

          <div 
            className="prose prose-sm dark:prose-invert max-w-none prose-p:leading-relaxed prose-a:text-blue-600"
            dangerouslySetInnerHTML={{ __html: email.body.html }} 
          />

          <div className="mt-12 pt-6 border-t flex gap-3">
            <button className="flex items-center gap-2 px-4 py-2 text-sm font-medium border rounded-full hover:bg-zinc-50 dark:hover:bg-zinc-900 transition-colors text-zinc-700 dark:text-zinc-300 shadow-sm">
              <Reply className="w-4 h-4" /> Reply
            </button>
            <button className="flex items-center gap-2 px-4 py-2 text-sm font-medium border rounded-full hover:bg-zinc-50 dark:hover:bg-zinc-900 transition-colors text-zinc-700 dark:text-zinc-300 shadow-sm">
              <Forward className="w-4 h-4" /> Forward
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
